let walkData=null,walkRecord=null,walkError='',walkSaveError='',walkGeneration=0,walkEditVersion=0,walkDirty=false,walkPending=null,walkFinishPending=null,walkUploadPending=null,walkSaving=null,walkTimer=null,walkSigning=null;
let walkReviewers=[],walkNumberingPending=null,walkCarryPending=null,walkFileRejected=false;
function resetWalks(){abortWalkDictation();walkFileRejected=false;auditRegister=false;auditActionRows=null;auditAction=null;auditActionEdit=null;auditActionPending=null;auditActionError='';auditActionFilter='Open';auditActionQuery='';walkReviewers=[];walkNumberingPending=null;walkCarryPending=null;clearTimeout(walkTimer);walkGeneration++;walkData=null;walkRecord=null;walkError='';walkSaveError='';walkEditVersion=0;walkDirty=false;walkPending=null;walkFinishPending=null;walkUploadPending=null;walkSaving=null;walkSigning=null}
const walkCacheKey=()=> 'panelstock-monthly-walk:'+actor.username;
function cachedWalk(){try{const v=JSON.parse(localStorage.getItem(walkCacheKey())||'null');return v?.record?.createdBy===actor.username?v:null}catch{return null}}
function cacheWalk(){if(!actor||!walkRecord||walkRecord.createdBy!==actor.username)return;try{if(walkRecord.status==='Completed')localStorage.removeItem(walkCacheKey());else localStorage.setItem(walkCacheKey(),JSON.stringify({record:walkRecord,dirty:walkDirty,version:walkEditVersion,pending:walkPending,finish:walkFinishPending}))}catch{notify('Device storage is unavailable. Save this walk to your account before leaving.')}}
function auditDictationContext(){return JSON.stringify([actor?.username,walkGeneration,page,auditRegister,walkRecord?.id,walkRecord?.status,auditAction?.originAuditId,auditAction?.originActionId])}
async function settleAuditDictation(){const context=auditDictationContext();return await finishWalkDictation()?context:null}
function walkStatus(){const el=document.getElementById('walk-save-status');if(el)el.textContent=walkFinishPending?'Completion not yet confirmed. Retry to confirm the signed record.':walkSaveError?'Not synced: '+walkSaveError:walkSaving?'Saving to your account…':walkDirty?'Unsaved changes on this device':'Saved to your account'}
function walkChanged(){if(busy||walkFinishPending)return;if(walkFileRejected){walkFileRejected=false;walkSaveError='';}document.querySelectorAll('#main [aria-invalid="true"]').forEach(el=>el.removeAttribute('aria-invalid'));walkDirty=true;walkEditVersion++;walkSigning=null;cacheWalk();walkStatus();clearTimeout(walkTimer);if(!walkSaveError||walkUploadPending)walkTimer=setTimeout(()=>void syncWalk(),900)}
function applyWalkMetadata(data){if(data.reviewers)walkReviewers=data.reviewers;if(data.numbering&&walkData)walkData.numbering=data.numbering;}
function walkSet(path,value){if(busy||walkFinishPending)return;let target=walkRecord;const keys=path.split('.');for(const k of keys.slice(0,-1))target=target[k];target[keys.at(-1)]=value;if(path==='date'){const dates=walkSchedule(value);walkRecord.month=value.slice(0,7);walkRecord.review.date=dates.reviewDate;walkRecord.review.nextAuditDue=dates.nextAuditDue;for(const [id,v] of [['walk-review-date',dates.reviewDate],['walk-review-nextAuditDue',dates.nextAuditDue]]){const el=document.getElementById(id);if(el)el.value=v;}}if(/^carriedActions\.\d+\.status$/.test(path)){walkFlagCarried(walkRecord);view('walks')}walkChanged()}
function walkResult(index,value){if(busy||walkFinishPending)return;const a=walkRecord.answers[index];if(!['NC','O'].includes(value)&&(walkRecord.carriedActions||[]).some(v=>v.ref===a.ref&&v.status!=='Closed')){view('walks');return notify('This point has an open brought-forward corrective action. Close or resolve the action before marking it compliant.');}a.result=value;if(['NC','O'].includes(value)){if(![...walkRecord.actions,...(walkRecord.carriedActions||[]).filter(v=>v.status!=='Closed')].some(v=>v.ref===a.ref))walkRecord.actions.push(walkNewAction(walkRecord,a.ref,true));}else walkRecord.actions=walkRecord.actions.filter(v=>v.ref!==a.ref||walkActionHasEvidence(v.id)||!walkUnusedAction(v,walkRecord.signerName));walkChanged();view('walks')}
async function syncWalk(){
 if(walkFinishPending)return false;if(walkSaving)return walkSaving;if(!walkDirty&&!walkPending&&!walkUploadPending)return true;if(!walkRecord||walkRecord.status!=='Draft'||walkRecord.createdBy!==actor?.username)return true;
 const id=walkRecord.id,generation=walkGeneration,username=actor.username;
 walkSaving=(async()=>{try{while(walkDirty||walkPending||walkUploadPending){if(walkUploadPending){if(!await postWalkUpload())return false;continue;}if(!walkPending)walkPending={version:walkEditVersion,body:{record:structuredClone(walkRecord),expectedRevision:walkRecord.revision||0,mutationId:crypto.randomUUID()}};const packet=walkPending;cacheWalk();const {record}=await api('/toolbox/walks/'+id,packet.body);if(generation!==walkGeneration||actor?.username!==username||walkRecord?.id!==id)return false;walkPending=null;if(packet.version===walkEditVersion){walkRecord=record;walkDirty=false}else{Object.assign(walkRecord,{revision:record.revision,createdAt:record.createdAt,updatedAt:record.updatedAt,evidence:record.evidence,signerName:record.signerName,documentNo:record.documentNo,workflowVersion:record.workflowVersion,carrySource:record.carrySource,carriedForward:record.carriedForward,month:record.month,issueDate:record.issueDate,template:record.template,statement:record.statement});if(!walkRecord.carriedActions)walkRecord.carriedActions=record.carriedActions;walkFlagCarried(walkRecord);walkDirty=true;}walkSaveError='';walkFileRejected=false;cacheWalk();}return true}catch(e){if(generation===walkGeneration&&actor?.username===username){walkSaveError=e.message;walkFileRejected=!!e.walkFileRejected;if(e.status===410){localStorage.removeItem(walkCacheKey());walkRecord=null;walkDirty=false;walkPending=null;walkFinishPending=null;walkUploadPending=null;if(page==='walks')view('walks')}else cacheWalk();}return false}finally{if(generation===walkGeneration){walkSaving=null;walkStatus();}}})();walkStatus();return walkSaving;
}
async function saveWalkDraft(){if(busy)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;if(walkFinishPending)return confirmWalkCompletion();walkSaveError='';if(await syncWalk())notify('Monthly Audit draft saved to your account.');else notify(walkSaveError||'The save was not confirmed. Your draft is kept on this device.')}
async function openWalks(offset=0){if(!actor?.canRunToolbox||busy)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;if(auditActionPending){auditRegister=true;view('walks',false);return notify('Retry the pending action update before leaving.');}auditRegister=false;if(walkRecord&&walkRecord.createdBy===actor.username&&(walkDirty||walkPending||walkUploadPending)&&!await syncWalk())return notify(walkSaveError);const generation=walkGeneration,username=actor.username;walkRecord=null;walkData=null;walkError='';view('walks');try{const data=offset?await api('/toolbox/walks/list',{offset}):await api('/toolbox/walks');if(generation!==walkGeneration||actor?.username!==username)return;walkData=data;if(data.archivedDraftIds?.includes(cachedWalk()?.record.id))localStorage.removeItem(walkCacheKey());applyWalkMetadata(data);if(page==='walks')view('walks')}catch(e){if(generation!==walkGeneration||actor?.username!==username)return;walkError=e.message;if(page==='walks')view('walks')}}
async function newWalk(){if(busy||!walkData)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;const cache=cachedWalk();if(cache?.dirty||cache?.pending||cache?.finish)return notify('Resume and save the device draft before starting another walk.');const template=walkData.template,date=today();walkRecord={id:crypto.randomUUID(),templateId:template.id,status:'Draft',workflowVersion:2,carriedActions:[],carrySource:null,month:date.slice(0,7),date,auditors:actor.displayName||actor.username,area:'',previousReviewed:'',carriedForward:'',documentNo:'',issueDate:'',answers:template.sections.flatMap(s=>s.items.map(i=>({ref:i.ref,result:'',comments:''}))),actions:[],summary:{escalation:'',resources:'',findings:'',priorities:['','','']},review:{by:'',date:'',position:'',nextAuditDue:'',actionsAccepted:'',escalationRequired:'',comments:''},evidence:[],createdBy:actor.username,signerName:actor.displayName||actor.username,statement:template.statement,template,revision:0};walkPending=null;walkFinishPending=null;walkSaveError='';walkDirty=true;walkEditVersion++;cacheWalk();view('walks');await syncWalk();if(page==='walks')view('walks')}
async function loadWalk(id,saved=false){if(busy)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;if(auditActionPending){auditRegister=true;view('walks',false);return notify('Retry the pending action update before leaving.');}auditRegister=false;if(walkRecord?.id!==id&&(walkDirty||walkPending||walkUploadPending)&&!await syncWalk())return notify(walkSaveError);const generation=walkGeneration,username=actor.username;try{const data=await api('/toolbox/walks/'+id),{record}=data;if(generation!==walkGeneration||actor?.username!==username)return;applyWalkMetadata(data);const cache=cachedWalk();walkRecord=record;walkDirty=false;walkPending=null;walkFinishPending=null;walkSaveError='';if(record.archived){if(cache?.record.id===record.id)localStorage.removeItem(walkCacheKey());}else if(record.status==='Draft'&&!saved&&cache?.record.id===id&&(cache.dirty||cache.pending||cache.finish)){walkRecord=cache.record;walkDirty=cache.dirty;walkEditVersion=cache.version||0;walkPending=cache.pending;walkFinishPending=cache.finish;if(record.revision!==walkRecord.revision&&!walkPending)walkSaveError='Another device changed this walk. Download your unsaved copy before reopening the saved version.';}else if(record.status==='Completed'){cacheWalk();}walkUploadPending=null;walkCarryPending=null;if(!walkRecord.archived&&walkRecord.status==='Draft'&&walkRecord.createdBy===actor.username&&(walkRecord.workflowVersion!==2||walkRecord.carriedActions?.some(a=>a.registerRevision===undefined))&&!walkPending&&!walkFinishPending){walkDirty=true;walkEditVersion++;await syncWalk();}view('walks')}catch(e){const cache=cachedWalk();if(e.status===404&&cache?.record.id===id&&!cache.record.revision&&(cache.dirty||cache.pending)){walkRecord=cache.record;walkDirty=cache.dirty;walkPending=cache.pending;walkEditVersion=cache.version||0;walkFinishPending=cache.finish;walkSaveError='This draft is kept on this device. Retry save to upload it to your account.';view('walks')}else notify(e.message)}}
function walkBackup(){const data=cachedWalk();if(data)download('Monthly_Audit_unsaved_'+data.record.id+'.json',JSON.stringify(data,null,2),'application/json')}
function walkActionHasEvidence(id){return walkRecord.evidence.some(f=>f.actionId===id)||walkUploadPending?.body.action==='upload'&&walkUploadPending.body.actionId===id}
function walkRemoveAction(i){if(busy||walkFinishPending)return;const a=walkRecord.actions[i];if(walkActionHasEvidence(a.id))return notify('Confirm any pending photo upload and remove this action’s photos before removing the action.');if(walkRecord.answers.some(v=>v.ref===a.ref&&['NC','O'].includes(v.result))&&walkRecord.actions.filter(v=>v.ref===a.ref).length===1)return notify('NC and O checks require a corrective action. Change the check result to remove an unused action.');walkRecord.actions.splice(i,1);walkChanged();view('walks')}
function walkReviewer(value){if(busy||walkFinishPending)return;const reviewer=walkReviewers.find(a=>a.username===value);walkRecord.review.byAdminUsername=value;walkRecord.review.by=reviewer?.displayName||'';if(!walkRecord.review.position)walkRecord.review.position=reviewer?.title||'';walkChanged();view('walks')}
async function refreshWalkCarry(){if(busy||walkFinishPending)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;if(!await syncWalk())return notify(walkSaveError);if(busy||dictationContext!==auditDictationContext())return;const id=walkRecord.id,generation=walkGeneration,username=actor.username;if(!walkCarryPending||walkCarryPending.id!==id)walkCarryPending={id,body:{expectedRevision:walkRecord.revision,mutationId:crypto.randomUUID()}};busy=true;try{const {record}=await api('/toolbox/walks/'+id+'/carry-forward',walkCarryPending.body);if(generation!==walkGeneration||actor?.username!==username)return;walkCarryPending=null;walkMergeEvidence(record);view('walks');notify('Open actions refreshed from the previous completed audit.')}catch(e){notify(e.message)}finally{busy=false}}
async function saveAuditNumbering(){if(busy||!actor?.isAdmin||!walkData)return;const startNumber=document.getElementById('audit-start-number').value.trim(),generation=walkGeneration,username=actor.username;busy=true;try{for(;;){if(!walkNumberingPending)walkNumberingPending={startNumber,expectedRevision:walkData.numbering.revision,mutationId:crypto.randomUUID()};const sent=walkNumberingPending,data=await api('/toolbox/walks/numbering',sent);if(generation!==walkGeneration||actor?.username!==username)return;walkNumberingPending=null;walkData.numbering=data.numbering;if(sent.startNumber!==startNumber)continue;view('walks');notify('Monthly Audit numbering saved.');break;}}catch(e){notify(e.message)}finally{busy=false}}
function resizeWalkTextarea(el){if(!el?.style)return;el.style.height='0px';el.style.height=Math.max(44,(el.scrollHeight||42)+2)+'px'}
function resizeWalkTextareas(){document.querySelectorAll('textarea.walk-textarea').forEach(resizeWalkTextarea)}
window.addEventListener?.('resize',()=>{if(page==='walks')resizeWalkTextareas()});

function walkMissing(id,message){const el=document.getElementById(id);el?.setAttribute('aria-invalid','true');el?.scrollIntoView({behavior:'smooth',block:'center'});el?.focus({preventScroll:true});notify(message);return false}
function checkWalk(){const r=walkRecord;for(const [k,label] of Object.entries({date:'audit date',auditors:'auditor(s)',area:'factory / area',previousReviewed:'previous audit reviewed'}))if(!r[k]?.trim())return walkMissing('walk-'+k,'Complete '+label+'.');for(const [i,a] of r.answers.entries()){if(!a.result)return walkMissing('walk-result-'+i,'Choose a result for point '+a.ref+'.');if(['NC','O'].includes(a.result)&&![...r.actions,...(r.carriedActions||[])].some(v=>v.ref===a.ref))return walkMissing('walk-result-'+i,'Complete the corrective action for point '+a.ref+'.');}for(const [group,rows] of [['action',r.actions],['carried',r.carriedActions||[]]])for(const [i,a] of rows.entries()){for(const k of ['issue','risk','correctiveAction','owner','due'])if(!a[k]?.trim())return walkMissing('walk-'+group+'-'+i+'-'+k,'Complete '+k.replace('correctiveAction','corrective action')+' for '+(group==='carried'?'brought-forward ':'')+'action '+(i+1)+'.');if(['C','H'].includes(a.risk)){if(!a.immediateControl.trim())return walkMissing('walk-'+group+'-'+i+'-immediateControl','Record the immediate control for this Critical / High-risk issue.');if(a.status!=='Closed'&&!r.summary.escalation.trim())return walkMissing('walk-summary-escalation','Record the Critical / High-risk escalation to management.');}if(a.status==='Closed')for(const k of ['closeEvidence','verifiedBy','verifiedDate'])if(!a[k]?.trim())return walkMissing('walk-'+group+'-'+i+'-'+k,'Record close-out evidence and verification.');}if(r.review.byAdminUsername&&!walkReviewers.some(a=>a.username===r.review.byAdminUsername))return walkMissing('walk-review-by','Choose a current PanelStock admin reviewer.');return true}

async function beginWalkSignature(){if(busy||walkFinishPending)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;if(!checkWalk())return;if(!await syncWalk())return notify(walkSaveError);if(busy||dictationContext!==auditDictationContext())return;if(!checkWalk())return;walkSigning={record:structuredClone(walkRecord)};resetSignaturePdf();signing='walk';document.getElementById('sign-title').textContent=walkRecord.signerName;document.getElementById('sign-statement').textContent=walkRecord.statement;document.getElementById('sign-dialog').showModal();const c=document.getElementById('signature-pad');c.width=1000;c.height=350;clearPad()}
async function saveWalkSignature(){if(busy||!walkSigning)return;const r=structuredClone(walkSigning.record),hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(walkContent(r)));r.status='Completed';r.signature={image:document.getElementById('signature-pad').toDataURL('image/png'),at:new Date().toISOString(),contentHash:Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('')};if(!walkFinishPending)walkFinishPending={record:r,expectedRevision:r.revision,mutationId:crypto.randomUUID()};cacheWalk();return confirmWalkCompletion()}
async function confirmWalkCompletion(){if(busy||!walkFinishPending)return;const packet=walkFinishPending,generation=walkGeneration,username=actor.username;busy=true;try{const {record}=await api('/toolbox/walks/'+packet.record.id,packet);if(generation!==walkGeneration||actor?.username!==username)return;walkRecord=record;walkFinishPending=null;walkPending=null;walkDirty=false;walkSaveError='';walkFileRejected=false;walkSigning=null;cacheWalk();document.getElementById('sign-dialog').close();view('walks');notify('Signed Monthly Audit and PDF saved. You can download the PDF and supporting files.')}catch(e){if(generation===walkGeneration){walkSaveError=e.message;if([400,409].includes(e.status)){walkFinishPending=null;walkSigning=null;document.getElementById('sign-dialog').close();cacheWalk();view('walks');notify('Review required: '+e.message);}else{cacheWalk();notify('Completion was not confirmed: '+e.message+' Retry to confirm the signed record.');}}}finally{busy=false;walkStatus()}}
async function walkDownload(path,body){try{const data=await api(path,body);download(data.fileName,Uint8Array.from(atob(data.data),c=>c.charCodeAt(0)),data.mime)}catch(e){notify(e.message)}}
async function downloadSavedAuditReport(id,kind){
 if(busy||!actor?.canRunToolbox||typeof id!=='string'||!/^[a-f0-9-]{36}$/i.test(id)||!['actions-pdf','actions-closeout-pdf'].includes(kind))return;
 await walkDownload('/toolbox/walks/'+id+'/'+kind);
}
async function downloadAuditActions(id=walkRecord?.status==='Completed'?walkRecord.id:null){await downloadSavedAuditReport(id,'actions-pdf')}
async function downloadAuditCloseout(id=walkRecord?.status==='Completed'?walkRecord.id:null){await downloadSavedAuditReport(id,'actions-closeout-pdf')}
async function downloadWalkPdf(){if(walkRecord?.status==='Completed')await walkDownload('/toolbox/walks/'+walkRecord.id+'/pdf')}
async function walkFileDownload(id){if(walkRecord)await walkDownload('/toolbox/walks/'+walkRecord.id+'/file',{action:'download',fileId:id,mutationId:crypto.randomUUID()})}
function walkMergeEvidence(record,version=walkEditVersion){
 // An uncertain file request can be confirmed after the user has typed more.
 // Advance only its authoritative revision/evidence; retain those newer edits.
 if(version===walkEditVersion&&!walkDirty&&!walkPending)walkRecord=record;
 else{Object.assign(walkRecord,{revision:record.revision,evidence:record.evidence,updatedAt:record.updatedAt,signature:null});walkDirty=true;}
 walkSaveError='';walkFileRejected=false;walkSigning=null;cacheWalk();
}
async function postWalkUpload(){
 const p=walkUploadPending,generation=walkGeneration,username=actor.username;
 let record;try{({record}=await api('/toolbox/walks/'+p.id+'/file',p.body));}catch(error){if(error.status===400&&generation===walkGeneration&&actor?.username===username&&walkRecord?.id===p.id&&walkUploadPending===p){walkUploadPending=null;error.walkFileRejected=true;}throw error;}
 if(generation!==walkGeneration||actor?.username!==username||walkRecord?.id!==p.id||walkUploadPending!==p)return false;
 // If our file mutation took revision N, a competing save of N could not
 // have committed. Rebuild that failed save from the latest local edits with
 // a fresh mutation ID; never rebase a conflict against another device.
 if(walkPending?.body.expectedRevision===p.body.expectedRevision&&record.revision===p.body.expectedRevision+1){walkPending=null;walkDirty=true;}
 walkUploadPending=null;walkMergeEvidence(record,p.version);return true;
}
async function walkFileData(file){if(file.size>5*1024*1024&&!file.type.startsWith('image/'))throw Error('Choose a file up to 5 MB.');const raw=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read this file.'));reader.readAsDataURL(file)});if(file.type.startsWith('image/')){if(file.size>15*1024*1024)throw Error('Choose a photo up to 15 MB.');const img=new Image();try{img.src=raw;await img.decode();const c=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);return {fileName:file.name.replace(/\.[^.]*$/,'')+'.jpg',mime:'image/jpeg',data:c.toDataURL('image/jpeg',.8).split(',')[1]}}finally{img.removeAttribute('src')}}const ext=file.name.split('.').at(-1).toLowerCase(),mime={pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',txt:'text/plain'}[ext];if(!mime)throw Error('Choose a PDF, photo, DOCX, XLSX or text file.');return {fileName:file.name,mime,data:raw.split(',')[1]}}
async function walkUpload(input,ref,actionId=''){
 if(busy||walkFinishPending)return;
 const files=[...input.files],dictationContext=await settleAuditDictation();
 if(!dictationContext||busy||dictationContext!==auditDictationContext())return;
 const generation=walkGeneration,username=actor.username,id=walkRecord.id,sameWalk=()=>generation===walkGeneration&&actor?.username===username&&walkRecord?.id===id;
 // Claim the UI lock before waiting for autosave, so two selections cannot
 // both pass the same save and submit the same expected revision.
 busy=true;clearTimeout(walkTimer);document.querySelector('.shell').inert=true;
 try{
  if(!await syncWalk())throw Error(walkSaveError||'The draft save was not confirmed.');
  if(!sameWalk())return;
  for(const file of files){
   const data=await walkFileData(file);if(!sameWalk())return;
   walkUploadPending={id,version:walkEditVersion,body:{...data,ref,...(actionId?{actionId}:{}),action:'upload',expectedRevision:walkRecord.revision,mutationId:crypto.randomUUID()}};
   if(!await syncWalk())throw Error(walkSaveError||'The upload was not confirmed.');
   if(!sameWalk())return;
  }
  notify('Evidence uploaded to point '+ref+'.');
 }catch(e){if(sameWalk())notify('Upload not confirmed: '+e.message+(walkUploadPending?' Retry the pending evidence change.':'')+(files.length>1?' Then select any remaining files again.':''));}
 finally{busy=false;document.querySelector('.shell').inert=false;input.value='';if(sameWalk()&&page==='walks')view('walks');}
}
async function retryWalkUpload(){
 if(busy||!walkUploadPending)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;
 busy=true;clearTimeout(walkTimer);
 try{if(await syncWalk()){view('walks');notify('Evidence change and draft saved.');}else notify(walkSaveError||'The evidence change was not confirmed.');}
 finally{busy=false;}
}
async function removeWalkFile(file){
 if(busy||walkFinishPending)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;
 const generation=walkGeneration,username=actor.username,id=walkRecord.id,sameWalk=()=>generation===walkGeneration&&actor?.username===username&&walkRecord?.id===id;
 busy=true;clearTimeout(walkTimer);
 try{
  if(!await syncWalk())return notify(walkSaveError);
  if(!sameWalk())return;
  // A prior removal may have committed even though its response was lost.
  if(!walkRecord.evidence.some(f=>f.id===file.id))return;
  walkUploadPending={id,version:walkEditVersion,body:{action:'delete',ref:file.ref,...(file.actionId?{actionId:file.actionId}:{}),fileId:file.id,expectedRevision:walkRecord.revision,mutationId:crypto.randomUUID()}};
  if(!await syncWalk())notify(walkSaveError||'Removal was not confirmed. Retry the pending evidence change.');
 }finally{busy=false;if(sameWalk()&&page==='walks')view('walks');}
}
function walkField(id,label,path,value,type='text',disabled=false){return `<div><label for="${id}">${esc(label)}</label><input id="${id}" type="${type}" value="${esc(value)}" maxlength="${type==='text'?240:10}" ${disabled?'disabled':''} oninput="walkSet('${path}',this.value)"></div>`}
function walkText(id,label,path,value,disabled=false,max=2000,readOnly=false){return `<div><label for="${id}">${esc(label)}</label><textarea id="${id}" class="walk-textarea" rows="1" maxlength="${max}" ${readOnly?'readonly':''} ${disabled?'disabled':''} oninput="walkSet('${path}',this.value);resizeWalkTextarea(this)">${esc(value)}</textarea>${walkDictationControls(id,disabled||readOnly)}</div>`}
function walkSelect(id,label,path,value,options,disabled=false){return `<div><label for="${id}">${esc(label)}</label><select id="${id}" ${disabled?'disabled':''} onchange="walkSet('${path}',this.value)">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`}
function walkEvidence(ref,editable){const files=walkRecord.evidence.filter(f=>f.ref===ref&&!f.actionId),help='walk-files-help-'+ref;return `<div class="walk-evidence"><div class="walk-evidence-heading"><strong>Supporting evidence</strong><span class="walk-evidence-count">${files.length} / 5 files</span></div>${files.length?`<ul class="walk-evidence-list">${files.map(f=>`<li><div class="walk-evidence-file"><strong>${esc(f.fileName)}</strong><span>${Math.ceil(f.size/1024)} KB</span></div><div class="walk-evidence-actions"><button onclick="walkFileDownload('${esc(f.id)}')" aria-label="Download ${esc(f.fileName)}">Download</button>${editable?`<button class="danger" onclick="removeWalkFile(walkRecord.evidence.find(f=>f.id==='${esc(f.id)}'))" aria-label="Remove ${esc(f.fileName)}">Remove</button>`:''}</div></li>`).join('')}</ul>`:''}${editable?`<div class="walk-evidence-upload"><label class="walk-upload" for="walk-files-${esc(ref)}"><input id="walk-files-${esc(ref)}" type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.heic,.heif,.webp,.docx,.xlsx,.txt,image/*" aria-label="Add evidence for point ${esc(ref)}" aria-describedby="${esc(help)}" ${files.length>=5?'disabled':''} onchange="walkUpload(this,'${esc(ref)}')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 16V4m-4 4 4-4 4 4M4 16v4h16v-4"/></svg><span>${files.length>=5?'Five-file limit reached':'Add files or photos'}</span></label><p id="${esc(help)}" class="muted">PDF, photos, DOCX, XLSX or text · 5 MB each<br>Photos resize automatically. Originals are saved with the audit.</p></div>`:!files.length?'<p class="muted">No supporting files.</p>':''}</div>`}

function walkActionHTML(a,i,editable,carried=false){
 const disabled=!editable,kind=carried?'carried':'action',id='walk-'+kind+'-'+i,path=(carried?'carriedActions.':'actions.')+i;
 return `<div class="walk-inline-action" data-action-point="${esc(a.ref)}"><h4>${carried?'Brought-forward action':'Corrective action'} ${i+1}${a.ref?' · Point '+esc(a.ref):''}</h4>${carried?'<p class="muted">Originally raised in '+esc(a.originDocumentNo)+'</p>':''}
 <div class="grid">${walkText(id+'-issue','Issue / location'+(a.ref&&!carried?' (automatic)':''),path+'.issue',a.issue,disabled,2000,!!a.ref||carried)}${walkSelect(id+'-risk','Risk',path+'.risk',a.risk,[['','Choose a risk'],['C','Critical'],['H','High'],['M','Medium'],['L','Low']],disabled)}</div>
 <div class="grid">${walkText(id+'-immediateControl','Immediate control',path+'.immediateControl',a.immediateControl,disabled)}${walkText(id+'-correctiveAction','Corrective action required',path+'.correctiveAction',a.correctiveAction,disabled)}</div>
 <div class="grid">${walkField(id+'-owner','Owner',path+'.owner',a.owner,'text',disabled)}${walkField(id+'-due','Due date',path+'.due',a.due,'date',disabled)}${walkSelect(id+'-status','Status',path+'.status',a.status,['Open','In progress','Closed'],disabled)}${walkText(id+'-closeEvidence','Close-out evidence',path+'.closeEvidence',a.closeEvidence,disabled)}${walkField(id+'-verifiedBy','Verified by',path+'.verifiedBy',a.verifiedBy,'text',disabled)}${walkField(id+'-verifiedDate','Verification date',path+'.verifiedDate',a.verifiedDate,'date',disabled)}</div>
 ${walkActionPhotos(a,editable)}${editable&&!carried?`<button class="danger" onclick="walkRemoveAction(${i})">Remove action</button>`:''}</div>`;
}
function auditNumberingHTML(){if(!walkData?.numbering)return '';const n=walkData.numbering;return `<details class="card"><summary>Document numbering</summary><p>Next Monthly Audit: <strong>${esc(n.nextDocumentNumber)}</strong>. A number is reserved for each new audit and retained when the draft is resumed.</p>${actor.isAdmin?`<label for="audit-start-number">Starting / next document number</label><input id="audit-start-number" maxlength="80" value="${esc(n.nextDocumentNumber)}"><button onclick="saveAuditNumbering()">Save document numbering</button>`:'<p class="muted">A PanelStock admin can set the starting document number.</p>'}</details>`;}
function walksHTML(){
 if(auditRegister)return auditActionsHTML();
 if(!walkRecord){const cache=cachedWalk(),rows=walkData?.records||[];return `<div class="row between"><div><h2>Monthly Audit</h2><p class="muted">Lennox Facades · Monthly factory safety audit and corrective actions</p></div><button onclick="openWalks()">Refresh</button></div>
 ${cache&&(cache.dirty||cache.pending||cache.finish)?`<div class="notice"><p>An unfinished audit is kept on this device.</p><div class="row"><button onclick="loadWalk('${esc(cache.record.id)}')">Resume device draft</button><button onclick="walkBackup()">Download unsaved copy</button><button class="danger" onclick="discardWalkDeviceCopy()">Discard device copy</button></div></div>`:''}
 <div class="card"><h3>Standard monthly audit</h3><p>23 inspection points, supporting files, corrective actions, management review and a final signature.</p>${walkData?`<p class="notice">${walkData.completedThisMonth>0?'A completed audit is recorded this month.':'The monthly audit is due. No completed audit is recorded for this month.'}</p><div class="row"><button class="primary" onclick="newWalk()">Start Monthly Audit</button><button onclick="walkDownload('/toolbox/walks/template')">Download original template</button></div>`:walkError?`<p class="notice">${esc(walkError)}</p>`:'<p role="status">Loading monthly audits…</p>'}</div>
 <div class="card"><h3>Corrective actions</h3><p>Follow up, attach photos and close out actions between audits.</p><button class="primary" onclick="openAuditActions()">Open corrective actions</button></div>${auditNumberingHTML()}<div class="card"><h3>Recent audits</h3>${rows.map(r=>`<div class="person"><div class="row between"><strong>${esc(r.documentNo)||'Monthly Audit'} · ${esc(displayDate(r.date))} · ${esc(r.area)||'Draft audit'}</strong><span class="tag">${esc(r.status)}</span></div><p class="muted">${esc(r.auditors)} · ${r.totals.open} open actions${r.totals.overdue?' · '+r.totals.overdue+' overdue':''}</p><div class="row"><button onclick="loadWalk('${esc(r.id)}')">${r.status==='Draft'?'Open draft':'View signed audit & reports'}</button>${r.status==='Completed'?`<button onclick="downloadAuditActions('${esc(r.id)}')">Corrective actions PDF</button>`:''}${r.status==='Draft'&&r.createdBy===actor.username?`<button class="danger" onclick="deleteWalkDraft('${esc(r.id)}')">Delete draft</button>`:''}</div></div>`).join('')||'<p class="empty">No audits saved yet.</p>'}${walkData?.nextOffset!==null&&walkData?`<button onclick="openWalks(${walkData.nextOffset})">Older audits</button>`:''}${walkData&&walkData.total>25?'<button onclick="openWalks()">Latest audits</button>':''}</div>`;}
 const r=walkRecord,template=r.template||walkData?.template,editable=!r.archived&&r.status==='Draft'&&r.createdBy===actor.username&&!walkFinishPending,disabled=!editable,t=walkTotals(r,today()),yn=['',['Yes','Yes'],['No','No']];let answerIndex=0;
 return `<div class="row between"><div><h2>Monthly Audit${r.documentNo?' · '+esc(r.documentNo):''}</h2><p class="muted">${esc(r.area)||'Factory safety audit'} · ${r.archived?'Archived · ':''}${esc(r.status)} · ${esc(r.signerName)}</p></div><button onclick="openWalks()">Back to audits</button></div>
 <p id="walk-save-status" class="notice" role="status">${walkFinishPending?'Completion not yet confirmed. Retry to confirm the signed record.':walkSaveError?'Not synced: '+esc(walkSaveError):walkDirty?'Unsaved changes on this device':'Saved to your account'}</p>
 ${walkSaveError?'<div class="row"><button onclick="saveWalkDraft()">Retry save</button><button onclick="walkBackup()">Download unsaved copy</button><button onclick="loadWalk(walkRecord.id,true)">Reopen saved version</button></div>':''}${walkUploadPending?'<p class="notice">An evidence change is not yet confirmed.</p><button onclick="retryWalkUpload()">Retry evidence change</button>':''}${walkFinishPending?'<button class="primary" onclick="confirmWalkCompletion()">Confirm signed completion</button>':''}
 ${r.status==='Completed'?'<div class="row"><button class="primary" onclick="downloadWalkPdf()">Download signed Monthly Audit PDF</button><button onclick="downloadAuditActions()">Download Corrective Actions Report</button><button onclick="downloadAuditCloseout()">Download Close-out Report</button></div><p class="muted">The Close-out Report includes completed actions and their latest saved evidence, with a count of actions still open.</p>':''}
 <div class="card"><h3>Audit details</h3><div class="grid">${[['date','Audit date','date'],['auditors','Auditor(s)','text'],['area','Factory / area','text']].map(([k,label,type])=>walkField('walk-'+k,label,k,r[k],type,disabled)).join('')}${walkSelect('walk-previousReviewed','Previous audit reviewed','previousReviewed',r.previousReviewed,[['','Choose Yes or No'],'Yes','No'],disabled)}${walkField('walk-carriedForward','Open actions brought forward (automatic)','carriedForward',r.carriedForward,'text',true)}${walkField('walk-documentNo','Document number (automatic)','documentNo',r.documentNo||'Assigned when saved','text',true)}</div></div>
 <section class="card"><h3>Open actions brought forward · ${(r.carriedActions||[]).length}</h3><p class="muted">${r.carrySource?'Previous audit: '+esc(r.carrySource.documentNo||'Legacy audit')+' · '+esc(displayDate(r.carrySource.date)):''} Unresolved actions automatically flag their inspection point below.</p>${(r.carriedActions||[]).filter(a=>a.ref).map(a=>`<p><span class="tag">${esc(a.status)}</span> <a href="#walk-check-${esc(a.ref)}">Point ${esc(a.ref)} · ${esc(a.issue)}</a></p>`).join('')}${(r.carriedActions||[]).map((a,i)=>!a.ref?walkActionHTML(a,i,editable,true):'').join('')}${!r.carriedActions?.length?'<p>No open actions brought forward.</p>':''}${editable?'<button onclick="refreshWalkCarry()">Refresh open corrective actions</button>':''}</section>
 ${r.actions.some(a=>!a.ref)?`<section class="card"><h3>Additional corrective actions</h3>${r.actions.map((a,i)=>!a.ref?walkActionHTML(a,i,editable):'').join('')}</section>`:''}
 <p class="notice">C = Compliant · NC = Non-compliant · O = Observation / improvement · N/A = Not applicable. NC and O automatically create a corrective action below the check. Open actions brought forward flag their point automatically. Apply immediate controls and escalate Critical / High risks before work continues.</p>
 ${template.sections.map(section=>`<section class="card"><h3>${esc(section.title)}</h3>${section.items.map(item=>{const i=answerIndex++,a=r.answers[i];return `<div class="topic" id="walk-check-${esc(item.ref)}" data-check-ref="${esc(item.ref)}"><h4>${esc(item.ref)} · ${esc(item.label)}</h4><label for="walk-result-${i}">Result</label><select id="walk-result-${i}" ${disabled?'disabled':''} onchange="walkResult(${i},this.value)">${[['','Choose a result'],['C','C — Compliant'],['NC','NC — Non-compliant'],['O','O — Observation / improvement'],['N/A','N/A — Not applicable']].map(([v,label])=>`<option value="${v}" ${a.result===v?'selected':''}>${label}</option>`).join('')}</select>
 ${(r.carriedActions||[]).some(v=>v.ref===item.ref&&v.status!=='Closed')?'<p class="notice">Brought-forward corrective action — follow-up required.</p>':''}${(r.carriedActions||[]).map((action,j)=>action.ref===item.ref?walkActionHTML(action,j,editable,true):'').join('')}${r.actions.map((action,j)=>action.ref===item.ref?walkActionHTML(action,j,editable):'').join('')}${walkEvidence(item.ref,editable)}</div>`}).join('')}</section>`).join('')}
 <section class="card"><h3>Monthly Audit Summary</h3><p>${t.inspected} inspected · ${t.compliant} compliant · ${t.nonCompliant} non-compliant · ${t.observations} observations · ${t.notApplicable} N/A</p><p>${r.actions.length} actions raised in this audit · ${(r.carriedActions||[]).length} brought forward</p><p>${t.closed} actions closed · ${t.open} open · ${t.overdue} overdue</p>${walkText('walk-summary-escalation','Critical / High-risk issues requiring escalation','summary.escalation',r.summary.escalation,disabled,3000)}${walkText('walk-summary-resources','Resources or support required','summary.resources',r.summary.resources,disabled,3000)}${walkText('walk-summary-findings','Key findings and recurring trends','summary.findings',r.summary.findings,disabled,5000)}</section>
 <section class="card"><h3>Management Review and Approval</h3><p class="muted">The review is scheduled for the last Friday of the audit month; the next audit is due on the first Monday of the following month.</p><div class="grid"><div><label for="walk-review-by">Reviewed by</label><select id="walk-review-by" ${disabled?'disabled':''} onchange="walkReviewer(this.value)"><option value="">Select a PanelStock admin</option>${r.review.byAdminUsername&&!walkReviewers.some(a=>a.username===r.review.byAdminUsername)?`<option selected disabled value="${esc(r.review.byAdminUsername)}">${esc(r.review.by)} (no longer an admin)</option>`:''}${!r.review.byAdminUsername&&r.review.by?`<option selected disabled>${esc(r.review.by)} (saved reviewer)</option>`:''}${walkReviewers.map(a=>`<option value="${esc(a.username)}" ${a.username===r.review.byAdminUsername?'selected':''}>${esc(a.displayName)}</option>`).join('')}</select></div>
 ${walkField('walk-review-date','Review date (last Friday)','review.date',r.review.date,'date',true)}${walkField('walk-review-position','Position','review.position',r.review.position,'text',disabled)}${walkField('walk-review-nextAuditDue','Next audit date (first Monday)','review.nextAuditDue',r.review.nextAuditDue,'date',true)}${walkSelect('walk-review-actionsAccepted','Actions accepted','review.actionsAccepted',r.review.actionsAccepted,yn,disabled)}${walkSelect('walk-review-escalationRequired','Escalation required','review.escalationRequired',r.review.escalationRequired,yn,disabled)}</div>${walkText('walk-review-comments','Manager comments','review.comments',r.review.comments,disabled,3000)}</section>
 <section class="card"><h3>Person conducting the audit — sign-off</h3><p>${esc(r.statement)}</p>${r.signature?`<img class="signature-image" src="${esc(r.signature.image)}" alt="Signature of ${esc(r.signerName)}"><p class="muted">${esc(r.signerName)} · ${esc(stamp(r.signature.at))}</p>`:`<p class="muted">${esc(r.signerName)} will sign before completion.</p>`}</section>${editable?'<div class="actions"><button class="danger" onclick="deleteWalkDraft(walkRecord.id)">Delete draft</button><button onclick="saveWalkDraft()">Save draft</button><button class="primary" onclick="beginWalkSignature()">Review, sign &amp; complete</button></div>':''}`;
}

document.getElementById('sign-dialog').addEventListener('close',()=>{if(signing==='walk'&&walkFinishPending&&actor&&page==='walks')view('walks')});

let auditRegister=false,auditActionRows=null,auditAction=null,auditActionEdit=null,auditActionPending=null,auditActionError='',auditActionFilter='Open',auditActionQuery='';
function actionCacheKey(){return 'panelstock-audit-action:'+actor.username+':'+auditAction.originAuditId+':'+auditAction.originActionId}
function cacheAuditAction(){if(!actor||!auditAction)return;try{localStorage.setItem(actionCacheKey(),JSON.stringify({edit:auditActionEdit,pending:auditActionPending,revision:auditAction.revision}))}catch{notify('Device storage is full. Keep this screen open and retry the action save.')}}
function actionPath(a=auditAction){return '/toolbox/walks/actions/'+a.originAuditId+'/'+a.originActionId}
async function openAuditActions(){if(busy)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;if(walkRecord&&(walkDirty||walkPending||walkUploadPending)&&!await syncWalk())return notify(walkSaveError);if(walkFinishPending)return notify('Confirm the signed audit before leaving.');if(auditActionPending){auditRegister=true;view('walks',false);return notify('Retry the pending action update before leaving.');}auditRegister=true;walkRecord=null;auditAction=null;auditActionEdit=null;auditActionRows=null;auditActionError='';const generation=walkGeneration,username=actor.username;view('walks',false);try{const data=await api('/toolbox/walks/actions');if(generation!==walkGeneration||actor?.username!==username)return;auditActionRows=data.actions;if(page==='walks'&&auditRegister)view('walks')}catch(e){auditActionError=e.message;if(page==='walks'&&auditRegister)view('walks')}}
async function openAuditAction(audit,id,saved=false){if(busy)return;const dictationContext=await settleAuditDictation();if(!dictationContext||busy||dictationContext!==auditDictationContext())return;const generation=walkGeneration,username=actor.username;try{const {action}=await api('/toolbox/walks/actions/'+audit+'/'+id);if(generation!==walkGeneration||actor?.username!==username)return;auditRegister=true;walkRecord=null;auditAction=action;auditActionEdit=structuredClone(action);auditActionPending=null;auditActionError='';if(!saved){let cache;try{cache=JSON.parse(localStorage.getItem(actionCacheKey())||'null')}catch{}if(cache?.edit){auditActionEdit=cache.edit;auditActionPending=cache.pending;if(cache.revision!==action.revision)auditActionError='This action changed since the device draft. Reload the saved version to review the latest follow-up.';}}else localStorage.removeItem(actionCacheKey());view('walks',false)}catch(e){notify(e.message)}}
function auditActionSet(key,value){if(busy||auditActionPending)return;auditActionEdit[key]=value;if(key==='status'&&value==='Closed'){auditActionEdit.verifiedBy||=actor.displayName||actor.username;auditActionEdit.verifiedDate||=today();view('walks')}cacheAuditAction()}
const auditActionFields=['status','owner','due','closeEvidence','verifiedBy','verifiedDate'];
function auditActionChanged(){return auditActionFields.some(key=>auditActionEdit[key]!==auditAction[key])}
function walkPhotoSource(file){return file.photoSource==='audit'||file.auditId?'audit':'closeout'}
function auditActionPhotoGroup(source){return auditAction.photos.filter(file=>walkPhotoSource(file)===source)}
async function postAuditAction(){
 const pending=auditActionPending,context=auditDictationContext(),edit=auditActionEdit;
 let action;
 try{({action}=await api(pending.path,pending.body))}
 catch(e){
  if(context===auditDictationContext()&&pending===auditActionPending&&pending.body.operation!=='update'&&[400,413].includes(e.status)){auditActionPending=null;cacheAuditAction();}
  throw e;
 }
 if(context!==auditDictationContext()||pending!==auditActionPending||pending.path!==actionPath())return false;
 auditAction=action;auditActionEdit=structuredClone(action);auditActionPending=null;auditActionError='';
 // Photo changes advance the saved revision, but do not submit the close-out form.
 if(pending.body.operation!=='update')for(const key of auditActionFields)auditActionEdit[key]=edit[key];
 if(auditActionChanged())cacheAuditAction();else localStorage.removeItem(actionCacheKey());
 return true;
}
async function saveAuditAction(){
 if(busy||!auditAction)return false;
 const context=await settleAuditDictation();if(!context||busy||context!==auditDictationContext())return false;
 const photoRetry=auditActionPending&&auditActionPending.body.operation!=='update';
 if(!auditActionPending){
  const a=auditActionEdit;
  for(const key of ['owner','due',...(a.status==='Closed'?['closeEvidence','verifiedBy','verifiedDate']:[])])if(!a[key]?.trim())return walkMissing('register-'+key,'Complete '+({closeEvidence:'close-out evidence',verifiedBy:'verified by',verifiedDate:'verification date'}[key]||key)+'.');
  auditActionPending={path:actionPath(),body:{operation:'update',expectedRevision:auditAction.revision,mutationId:crypto.randomUUID(),...Object.fromEntries(auditActionFields.map(k=>[k,a[k]]))}};cacheAuditAction();
 }
 busy=true;view('walks');
 try{
  if(!await postAuditAction())return false;
  notify(photoRetry?'Photo change saved.'+(auditActionChanged()?' Save follow-up to confirm the close-out details.':''):'Corrective action '+(auditAction.status==='Closed'?'closed and verified.':'follow-up saved.'));return true;
 }catch(e){if(context===auditDictationContext()){auditActionError=e.message;cacheAuditAction();notify('Action update not confirmed: '+e.message);}return false;}
 finally{busy=false;if(context===auditDictationContext())view('walks')}
}
async function auditActionPhotos(input){
 const files=[...input.files];input.value='';
 if(busy||!auditAction||auditActionPending||!files.length)return;
 if(files.some(file=>!file.type.startsWith('image/')))return notify('Choose photos for this corrective action.');
 if(files.some(file=>file.size>15*1024*1024))return notify('Choose photos up to 15 MB each.');
 const context=await settleAuditDictation();
 if(!context||busy||context!==auditDictationContext()||auditActionPending)return;
 if(auditActionPhotoGroup('closeout').length+files.length>5)return notify('Up to five close-out photos per action. Choose fewer photos or remove a close-out photo first.');
 busy=true;view('walks');
 try{
  for(const file of files){
   const data=await walkFileData(file);
   if(context!==auditDictationContext())return;
   auditActionPending={path:actionPath(),body:{...data,operation:'upload-photo',expectedRevision:auditAction.revision,mutationId:crypto.randomUUID()}};
   cacheAuditAction();if(!await postAuditAction())return;
  }
  notify('Photos saved.'+(auditActionChanged()?' Save follow-up to confirm the close-out details.':''));
 }catch(e){if(context===auditDictationContext()){auditActionError=e.message;cacheAuditAction();notify('Photo upload not confirmed: '+e.message+(auditActionPending?' Retry the pending update.':'')+(files.length>1?' Select any remaining photos again.':''));}}
 finally{busy=false;if(context===auditDictationContext())view('walks')}
}
async function removeAuditActionPhoto(id){
 if(busy||!auditAction||auditActionPending||!auditActionPhotoGroup('closeout').some(f=>f.id===id))return;
 const context=await settleAuditDictation();
 if(!context||busy||context!==auditDictationContext()||auditActionPending||!auditActionPhotoGroup('closeout').some(f=>f.id===id))return;
 busy=true;view('walks');
 try{
  auditActionPending={path:actionPath(),body:{operation:'remove-photo',fileId:id,expectedRevision:auditAction.revision,mutationId:crypto.randomUUID()}};
  cacheAuditAction();if(await postAuditAction())notify('Photo removed.');
 }catch(e){if(context===auditDictationContext()){auditActionError=e.message;cacheAuditAction();notify('Photo removal not confirmed: '+e.message+(auditActionPending?' Retry the pending update.':''));}}
 finally{busy=false;if(context===auditDictationContext())view('walks')}
}
function registerPhotoDownload(id){return walkDownload(actionPath(),{operation:'download-photo',fileId:id,mutationId:crypto.randomUUID()})}
async function downloadActionCloseout(){
 if(busy||auditAction?.status!=='Closed')return;
 const context=await settleAuditDictation();
 if(!context||busy||context!==auditDictationContext())return;
 if(auditActionEdit.status!=='Closed')return notify('Save the changed status before downloading a close-out report.');
 if(auditActionPending&&!await saveAuditAction())return;
 if(busy||context!==auditDictationContext())return;
 if(auditActionChanged()&&!await saveAuditAction())return;
 if(busy||context!==auditDictationContext()||auditAction?.status!=='Closed')return;
 await walkDownload('/toolbox/walks/'+auditAction.originAuditId+'/actions-closeout-pdf');
}
function auditOriginalPhotosHTML(){
 const photos=auditActionPhotoGroup('audit');
 return `<section class="card" aria-labelledby="register-audit-photos-title"><div class="walk-evidence-heading"><h3 id="register-audit-photos-title">Audit photos</h3><span class="walk-evidence-count">${photos.length} ${photos.length===1?'photo':'photos'}</span></div><p class="muted">Photos recorded during the audit are kept with the signed audit. Add photos of the completed work in Close-out photos below.</p>${photos.length?`<ul class="walk-evidence-list">${photos.map(f=>`<li><div class="walk-evidence-file"><strong>${esc(f.fileName)}</strong><span>${Math.ceil(f.size/1024)} KB</span></div><div class="walk-evidence-actions"><button onclick="registerPhotoDownload('${esc(f.id)}')" aria-label="View or download audit photo ${esc(f.fileName)}">View / download</button></div></li>`).join('')}</ul>`:'<p class="muted">No audit photos attached to this action.</p>'}</section>`;
}
function auditActionPhotosHTML(disabled){
 const photos=auditActionPhotoGroup('closeout'),full=photos.length>=5;
 return `<section class="walk-evidence" aria-labelledby="register-photos-title"><div class="walk-evidence-heading"><strong id="register-photos-title">Close-out photos</strong><span class="walk-evidence-count">${photos.length} / 5 photos</span></div><p class="muted">Attach photos showing the completed corrective work. These photos are included in the Close-out Report.</p>${photos.length?`<ul class="walk-evidence-list">${photos.map(f=>`<li><div class="walk-evidence-file"><strong>${esc(f.fileName)}</strong><span>${Math.ceil(f.size/1024)} KB</span></div><div class="walk-evidence-actions"><button onclick="registerPhotoDownload('${esc(f.id)}')">View / download</button><button class="danger" ${disabled?'disabled':''} onclick="removeAuditActionPhoto('${esc(f.id)}')" aria-label="Remove ${esc(f.fileName)}">Remove</button></div></li>`).join('')}</ul>`:''}<div class="walk-evidence-upload"><label class="walk-upload" for="register-photos-camera"><input id="register-photos-camera" type="file" accept="image/*" capture="environment" aria-label="Take a close-out photo" aria-describedby="register-photos-help" ${disabled||full?'disabled':''} onchange="auditActionPhotos(this)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 6h4l2-3h4l2 3h4v14H4z"/><circle cx="12" cy="12" r="4"/></svg><span>Take photo</span></label><label class="walk-upload" for="register-photos"><input id="register-photos" type="file" accept="image/*" multiple aria-label="Choose close-out photos" aria-describedby="register-photos-help" ${disabled||full?'disabled':''} onchange="auditActionPhotos(this)"><span>Choose photos</span></label><p id="register-photos-help" class="muted">${full?'Five close-out photos attached. Remove one to add another.':'Up to five close-out photos per action, separate from audit photos. Photos resize automatically.'}<br>Photos save when uploaded. Save follow-up to confirm your close-out details.</p></div></section>`;
}
function searchAuditActions(value){
 const before=document.getElementById('action-search'),start=before?.selectionStart,end=before?.selectionEnd;
 auditActionQuery=value;view('walks');
 const input=document.getElementById('action-search');input?.focus?.({preventScroll:true});if(start!=null&&end!=null)input?.setSelectionRange?.(start,end);
}
function auditActionsHTML(){
 if(!auditAction){const rows=auditActionRows||[],open=rows.filter(a=>a.status!=='Closed'),query=auditActionQuery.trim().toLowerCase(),visible=rows.filter(a=>(auditActionFilter==='All'||auditActionFilter==='Closed'?(auditActionFilter==='All'||a.status==='Closed'):a.status!=='Closed')&&(!query||[a.issue,a.owner,a.originDocumentNo,a.area,a.correctiveAction].join(' ').toLowerCase().includes(query)));return `<div class="row between audit-actions-heading"><div><h2>Corrective actions</h2><p class="muted">Track and close actions without starting an audit.</p></div><button onclick="openWalks()">Monthly Audits</button></div><div class="card audit-actions-filters"><div class="audit-action-counts" role="group" aria-label="Corrective action totals"><span class="audit-action-count"><strong>${auditActionRows?open.length:'—'}</strong><span>Open</span></span><span class="audit-action-count overdue"><strong>${auditActionRows?open.filter(a=>a.due&&a.due<today()).length:'—'}</strong><span>Overdue</span></span><span class="audit-action-count closed"><strong>${auditActionRows?rows.length-open.length:'—'}</strong><span>Closed</span></span></div><div class="audit-actions-toolbar"><div class="audit-actions-status"><label for="action-filter">Status</label><select id="action-filter" onchange="auditActionFilter=this.value;view('walks')">${['Open','Closed','All'].map(v=>`<option ${auditActionFilter===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="audit-actions-search"><label for="action-search">Search actions</label><input id="action-search" type="search" value="${esc(auditActionQuery)}" oninput="searchAuditActions(this.value)" placeholder="Issue, owner or audit number"></div><button class="audit-actions-refresh" onclick="openAuditActions()">Refresh actions</button></div></div><p class="muted audit-actions-results" role="status">${auditActionRows?`${visible.length} ${visible.length===1?'action':'actions'} shown`:auditActionError?'Actions unavailable':'Loading actions…'}</p>${auditActionError?`<p class="notice">${esc(auditActionError)}</p>`:''}${auditActionRows?visible.map(a=>`<div class="card audit-action-card"><div class="row between"><strong>${esc(a.originDocumentNo)}${a.ref?' · Point '+esc(a.ref):''}</strong><span class="tag">${esc(a.status)}${a.status!=='Closed'&&a.due<today()?' · Overdue':''}</span></div><h3>${esc(a.issue)}</h3><p>${esc(a.correctiveAction)}</p><p class="muted">${esc(a.owner)} · Due ${esc(displayDate(a.due))} · ${esc(a.area)}</p><div class="row audit-action-buttons"><button class="primary" onclick="openAuditAction('${esc(a.originAuditId)}','${esc(a.originActionId)}')">${a.status==='Closed'?'View close-out':'Update / close out'}</button><button onclick="downloadAuditActions('${esc(a.originAuditId)}')" aria-label="Download corrective actions report for ${esc(a.originDocumentNo)}">Actions report PDF</button>${a.status==='Closed'?`<button onclick="downloadAuditCloseout('${esc(a.originAuditId)}')" aria-label="Download audit close-out report for ${esc(a.originDocumentNo)}">Close-out PDF</button>`:''}</div></div>`).join('')||'<p class="card">No actions match this view.</p>':'<p role="status">Loading corrective actions…</p>'}`;}
 const a=auditAction,e=auditActionEdit,disabled=busy||!!auditActionPending,field=(key,label,type='text')=>`<div><label for="register-${key}">${label}</label><input id="register-${key}" type="${type}" value="${esc(e[key])}" maxlength="${type==='text'?160:10}" ${disabled?'disabled':''} oninput="auditActionSet('${key}',this.value)"></div>`;
 return `<div class="row between"><div><h2>Corrective action</h2><p class="muted">${esc(a.originDocumentNo)}${a.ref?' · Point '+esc(a.ref):''} · ${esc(a.area)}</p></div><button onclick="openAuditActions()">Back to actions</button></div><div class="card"><h3>${esc(a.issue)}</h3><p>${esc(a.correctiveAction)}</p><p class="muted">Risk: ${esc(({C:'Critical',H:'High',M:'Medium',L:'Low'})[a.risk]||a.risk)}</p>${a.immediateControl?`<p><strong>Immediate control:</strong> ${esc(a.immediateControl)}</p>`:''}</div>${auditOriginalPhotosHTML()}${auditActionError?`<p class="notice">${esc(auditActionError)}</p>`:''}<div class="card"><h3>Follow-up and close-out</h3><div class="grid"><div><label for="register-status">Status</label><select id="register-status" ${disabled?'disabled':''} onchange="auditActionSet('status',this.value)">${['Open','In progress','Closed'].map(v=>`<option ${e.status===v?'selected':''}>${v}</option>`).join('')}</select></div>${field('owner','Owner')}${field('due','Due date','date')}</div><label for="register-closeEvidence">Close-out evidence${e.status==='Closed'?' *':''}</label><textarea id="register-closeEvidence" class="walk-textarea" rows="1" maxlength="2000" ${disabled?'disabled':''} oninput="auditActionSet('closeEvidence',this.value);resizeWalkTextarea(this)">${esc(e.closeEvidence)}</textarea>${walkDictationControls('register-closeEvidence',disabled)}${auditActionPhotosHTML(disabled)}<div class="grid">${field('verifiedBy','Verified by'+(e.status==='Closed'?' *':''))}${field('verifiedDate','Verification date'+(e.status==='Closed'?' *':''),'date')}</div><div class="row"><button class="primary" onclick="saveAuditAction()">${auditActionPending?'Retry pending update':'Save follow-up'}</button><button onclick="openAuditAction('${esc(a.originAuditId)}','${esc(a.originActionId)}',true)">Reload saved version</button>${a.status==='Closed'?'<button onclick="downloadActionCloseout()">Download audit Close-out Report</button>':''}</div></div><div class="card"><h3>Action history</h3>${[...a.history].reverse().map(h=>`<div class="person"><strong>${esc(h.event)} · ${esc(h.status)}</strong><p class="muted">${esc(stamp(h.at))} · ${esc(h.by)}${h.auditDocumentNo?' · '+esc(h.auditDocumentNo):''}</p>${h.closeEvidence?`<p>${esc(h.closeEvidence)}</p>`:''}${h.verifiedBy?`<p class="muted">Verified by ${esc(h.verifiedBy)} · ${esc(displayDate(h.verifiedDate))}</p>`:''}</div>`).join('')||'<p class="muted">Raised in the original signed audit.</p>'}</div>`;
}

function walkActionPhotos(a,editable){
 const local=walkRecord.evidence.filter(f=>f.actionId===a.id),inherited=a.photos||[],files=[...inherited.filter(f=>walkPhotoSource(f)==='audit'),...local],closeout=inherited.filter(f=>walkPhotoSource(f)==='closeout'),id='walk-action-photos-'+a.id;
 const download=f=>local.some(v=>v.id===f.id)?`walkFileDownload('${esc(f.id)}')`:`walkDownload('/toolbox/walks/actions/${esc(a.originAuditId)}/${esc(a.originActionId)}',{operation:'download-photo',fileId:'${esc(f.id)}',mutationId:crypto.randomUUID()})`;
 const list=(photos,removable)=>`<ul class="walk-evidence-list">${photos.map(f=>`<li><div class="walk-evidence-file"><strong>${esc(f.fileName)}</strong><span>${Math.ceil(f.size/1024)} KB</span></div><div class="walk-evidence-actions"><button onclick="${download(f)}">View / download</button>${removable&&local.some(v=>v.id===f.id)?`<button class="danger" onclick="removeWalkFile(walkRecord.evidence.find(f=>f.id==='${esc(f.id)}'))">Remove</button>`:''}</div></li>`).join('')}</ul>`;
 return `<div class="walk-evidence"><div class="walk-evidence-heading"><strong>Audit photos</strong><span class="walk-evidence-count">${files.length} / 5 photos</span></div>${files.length?list(files,editable):''}${editable?`<div class="walk-evidence-upload"><label class="walk-upload" for="${id}"><input id="${id}" type="file" multiple accept="image/*" ${files.length>=5?'disabled':''} onchange="walkUpload(this,'${esc(a.ref)}','${esc(a.id)}')"><span>Add audit photos</span></label><p class="muted">Photos resize automatically and are included in the signed audit PDF.</p></div>`:''}</div>${closeout.length?`<div class="walk-evidence"><div class="walk-evidence-heading"><strong>Close-out photos</strong><span class="walk-evidence-count">${closeout.length} / 5 photos</span></div><p class="muted">From the corrective action register. These photos are kept separate from the audit photos.</p>${list(closeout,false)}</div>`:''}`;
}

function discardWalkDeviceCopy(){if(busy||!confirm('Discard the unsaved audit copy on this device? Saved account drafts will remain available.'))return;localStorage.removeItem(walkCacheKey());openWalks()}
async function deleteWalkDraft(id){if(busy||walkFinishPending)return;if(!confirm('Delete this Monthly Audit draft and its uploaded evidence? Its document number will not be reused.'))return;abortWalkDictation();if(walkRecord?.id===id&&(walkDirty||walkPending||walkUploadPending)&&!await syncWalk())return notify(walkSaveError);if(busy)return;clearTimeout(walkTimer);const generation=walkGeneration,username=actor.username;busy=true;try{const revision=walkRecord?.id===id?walkRecord.revision:walkData?.records.find(r=>r.id===id)?.revision;if(!Number.isSafeInteger(revision))throw Error('Refresh the audit list before deleting this draft.');await api('/toolbox/walks/'+id+'/delete',{expectedRevision:revision,mutationId:crypto.randomUUID()});if(generation!==walkGeneration||actor?.username!==username)return;if(cachedWalk()?.record.id===id)localStorage.removeItem(walkCacheKey());if(walkRecord?.id===id){walkRecord=null;walkDirty=false;walkPending=null;walkUploadPending=null;walkSaveError='';}notify('Monthly Audit draft deleted.');}catch(e){notify('Delete not confirmed: '+e.message+' Refresh the audit list to check its status.');}finally{busy=false;}if(generation===walkGeneration&&actor?.username===username&&!walkRecord)await openWalks()}
